/* pixel3d-ui — data group styles (component-specific keyframes/utilities). */

/* ── 1-step notched corners as a mask (for things that aren't `sticker`s:
      skeleton blocks, avatar images and fallbacks). A mask, never a clip-path polygon. ── */
@utility pixel-notch {
  -webkit-mask: conic-gradient(at 4px 4px, #000 75%, #0000 0) 0 0 / calc(100% - 4px) calc(100% - 4px) round;
  mask: conic-gradient(at 4px 4px, #000 75%, #0000 0) 0 0 / calc(100% - 4px) calc(100% - 4px) round;
}

/* ── table: dashed pixel separators between body rows ── */
@utility table-pixel-rows {
  & > tr {
    background-image: linear-gradient(90deg, rgb(20 20 20 / 0.3) 50%, transparent 50%);
    background-size: 8px 2px;
    background-repeat: repeat-x;
    background-position: 0 100%;
  }
  & > tr:last-child { background-image: none; }
}

/* ── skeleton: lid-deep block + a dithered 2×2 checker band that sweeps in steps() ── */
@keyframes p3d-dither-sweep {
  0% { -webkit-mask-position: 100% 0; mask-position: 100% 0; }
  100% { -webkit-mask-position: 0% 0; mask-position: 0% 0; }
}
@utility skeleton-dither {
  --p3d-dither: rgb(255 255 255 / 0.55);
  position: relative;
  background: var(--p3d-lid-deep);
  /* recessed: a soft inner lip from the light above */
  box-shadow: inset 0 4px 4px rgb(var(--p3d-shadow) / 0.12);
  &:where(.dark, .dark *) { --p3d-dither: rgb(255 255 255 / 0.09); }
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    /* 4px checker cells = a 2×2 dither tile on the 4px grid */
    background: conic-gradient(var(--p3d-dither) 25%, transparent 0 50%, var(--p3d-dither) 0 75%, transparent 0) 0 0 / 8px 8px;
    -webkit-mask: linear-gradient(90deg, #0000 0 40%, #0008 40% 44%, #000 44% 56%, #0008 56% 60%, #0000 60%) 100% 0 / 300% 100% no-repeat;
    mask: linear-gradient(90deg, #0000 0 40%, #0008 40% 44%, #000 44% 56%, #0008 56% 60%, #0000 60%) 100% 0 / 300% 100% no-repeat;
    animation: p3d-dither-sweep 1400ms steps(14) infinite;
  }
}

/* ── progress: an XP bar. The fill width is quantised to whole 8px blocks, so as the
      registered --p3d-pv animates the bar gains one block at a time. ── */
@property --p3d-pv {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}
@keyframes p3d-xp-scan {
  0% { margin-left: 0; }
  100% { margin-left: calc(100% - 24px); }
}
@utility xp-fill {
  height: 100%;
  width: calc(var(--p3d-pv) * 1%);
  width: round(down, calc(var(--p3d-pv) * 1%), 8px);
  background: repeating-linear-gradient(90deg, var(--color-pink) 0 6px, transparent 6px 8px);
  transition: --p3d-pv 700ms var(--ease-out-expo);
}
@utility xp-scan {
  width: 24px;
  height: 100%;
  background: repeating-linear-gradient(90deg, var(--color-pink) 0 6px, transparent 6px 8px);
  animation: p3d-xp-scan 1200ms steps(16) infinite alternate;
}

/* ── carousel: cover-flow. Embla writes --p3d-d (signed distance from centre, in slides)
      and --p3d-ad (its absolute value, clamped to 1) on every slide. ── */
@utility slide-flow {
  --p3d-k: min(var(--p3d-ad, 0), 1);
  transform:
    perspective(900px)
    translateY(calc(-8px * (1 - var(--p3d-k))))
    rotateY(calc(var(--p3d-d, 0) * -30deg))
    rotate(calc(var(--p3d-tilt, 0deg) * var(--p3d-k)))
    scale(calc(1.04 - var(--p3d-k) * 0.14));
  transform-origin: 50% 50%;
  will-change: transform;
  &[data-center] { --p3d-sh: 0 14px 14px rgb(var(--p3d-shadow) / 0.24); }
  @media (prefers-reduced-motion: reduce) {
    transform: rotate(calc(var(--p3d-tilt, 0deg) * var(--p3d-k)));
  }
}
@utility slide-flow-y {
  --p3d-k: min(var(--p3d-ad, 0), 1);
  transform:
    perspective(900px)
    rotateX(calc(var(--p3d-d, 0) * 26deg))
    rotate(calc(var(--p3d-tilt, 0deg) * var(--p3d-k)))
    scale(calc(1.04 - var(--p3d-k) * 0.14));
  will-change: transform;
  &[data-center] { --p3d-sh: 0 14px 14px rgb(var(--p3d-shadow) / 0.24); }
  @media (prefers-reduced-motion: reduce) {
    transform: rotate(calc(var(--p3d-tilt, 0deg) * var(--p3d-k)));
  }
}

/* ── chart: pixel styling for Recharts inside ChartContainer ── */
@utility chart-pixel {
  & .recharts-cartesian-axis-tick text,
  & .recharts-label,
  & .recharts-text {
    /* recharts writes fill: #666 inline on tick text */
    fill: currentColor !important;
    font-size: 14px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
  }
  & .recharts-cartesian-axis-line,
  & .recharts-cartesian-axis-tick-line {
    stroke: currentColor;
    stroke-width: 2px;
    shape-rendering: crispEdges;
  }
  & .recharts-cartesian-grid line {
    stroke: currentColor;
    stroke-opacity: 0.22;
    stroke-dasharray: 4 4;
    shape-rendering: crispEdges;
  }
  & .recharts-bar-rectangle path,
  & .recharts-rectangle {
    shape-rendering: crispEdges;
  }
  & .recharts-line-curve,
  & .recharts-area-curve {
    stroke-linejoin: miter;
    stroke-linecap: square;
    shape-rendering: crispEdges;
  }
  & .recharts-tooltip-cursor {
    stroke: currentColor;
    stroke-width: 2px;
    stroke-dasharray: 4 4;
    shape-rendering: crispEdges;
  }
  & .recharts-rectangle.recharts-tooltip-cursor {
    fill: currentColor;
    fill-opacity: 0.08;
    stroke: none;
  }
  & .recharts-surface { overflow: visible; }
  & .recharts-wrapper { outline: none; }
  & .recharts-sector, & .recharts-surface:focus { outline: none; }
}

/* pixel3d-ui — forms group styles (component-specific keyframes/utilities). */

/* pink fill in a 4px pixel checker (slider range) */
@utility pixel-fill-pink {
  background-color: var(--color-pink);
  background-image: conic-gradient(#ff7aae 25%, transparent 0 50%, #ff7aae 0 75%, transparent 0);
  background-size: 8px 8px;
  image-rendering: pixelated;
}

/* the pink block caret (input-otp slots) */
@keyframes p3d-caret-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
@utility animate-caret-blink { animation: p3d-caret-blink 1s steps(1) infinite; }

@layer components {
  /* ── slider thumb: crooked ink block, peels on hover, stays lifted while grabbed ── */
  [data-slot="slider-thumb-block"] {
    transform: rotate(var(--p3d-tilt, 0deg));
    transition: transform 260ms var(--ease-peel), filter 260ms var(--ease-peel);
  }
  [data-slot="slider-thumb"]:focus-visible > [data-slot="slider-thumb-block"] {
    --p3d-cut: var(--color-sky);
  }
  [data-slot="slider-thumb"]:not([data-disabled]):hover > [data-slot="slider-thumb-block"],
  [data-slot="slider"][data-dragging] [data-slot="slider-thumb"]:focus > [data-slot="slider-thumb-block"] {
    transform: translateY(-5px) rotate(0deg) scale(1.08);
    --p3d-sh: 0 14px 14px rgb(var(--p3d-shadow) / 0.24);
  }

  /* value sticker: hidden until you grab (or keyboard-focus) the thumb */
  [data-slot="slider-value"] {
    opacity: 0;
    transform: translate(-50%, 6px) scale(0.9);
    transition: opacity 120ms, transform 260ms var(--ease-peel);
  }
  [data-slot="slider"][data-dragging] [data-slot="slider-thumb"]:focus > [data-slot="slider-value"],
  [data-slot="slider-thumb"]:focus-visible > [data-slot="slider-value"] {
    opacity: 1;
    transform: translate(-50%, 0) scale(1);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="slider"] [data-slot="slider-thumb"] > [data-slot="slider-thumb-block"] {
      transform: rotate(var(--p3d-tilt, 0deg)) !important;
    }
  }
}

/* pixel3d-ui — kit group styles (component-specific keyframes/utilities). */

/* Countdown: a unit sticker flips over on its X axis when its number changes */
@keyframes p3d-flip {
  0% { transform: rotateX(0deg); }
  45% { transform: rotateX(-90deg); }
  46% { transform: rotateX(90deg); }
  80% { transform: rotateX(-10deg); }
  100% { transform: rotateX(0deg); }
}
@utility animate-flip { animation: p3d-flip 420ms var(--ease-peel) both; }

/* the number swaps exactly when the sticker is edge-on */
@keyframes p3d-flip-old { 0%, 45% { opacity: 1; } 46%, 100% { opacity: 0; } }
@keyframes p3d-flip-new { 0%, 45% { opacity: 0; } 46%, 100% { opacity: 1; } }
@utility animate-flip-old { animation: p3d-flip-old 420ms linear both; }
@utility animate-flip-new { animation: p3d-flip-new 420ms linear both; }

/* XP bar: a block lands in pixel steps */
@keyframes p3d-block-in {
  0% { transform: translateY(-10px) scale(1.3); opacity: 0; }
  50% { transform: translateY(2px) scale(0.9); opacity: 1; }
  100% { transform: none; opacity: 1; }
}
@utility animate-block-in { animation: p3d-block-in 180ms steps(3, end) both; }

/* Marquee: the track slides one copy's width, forever */
@keyframes p3d-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@utility marquee-track {
  animation: p3d-marquee var(--p3d-marquee-duration, 30s) linear infinite;
  animation-direction: var(--p3d-marquee-direction, normal);
}
@utility marquee-pause {
  &:hover .marquee-track, &:focus-within .marquee-track { animation-play-state: paused; }
}

/* Dropzone: an empty sticker slot, a stepped-dotted outline on the lid.
   Four dotted rules stop 8px short of each corner; a 4px dot steps each corner in. */
@utility sticker-slot {
  --slot-fill: color-mix(in srgb, var(--p3d-lid-deep) 60%, transparent);
  background-image:
    repeating-linear-gradient(90deg, currentColor 0 4px, transparent 4px 8px),
    repeating-linear-gradient(90deg, currentColor 0 4px, transparent 4px 8px),
    repeating-linear-gradient(180deg, currentColor 0 4px, transparent 4px 8px),
    repeating-linear-gradient(180deg, currentColor 0 4px, transparent 4px 8px),
    linear-gradient(currentColor, currentColor),
    linear-gradient(currentColor, currentColor),
    linear-gradient(currentColor, currentColor),
    linear-gradient(currentColor, currentColor),
    linear-gradient(var(--slot-fill), var(--slot-fill));
  background-size:
    calc(100% - 16px) 4px, calc(100% - 16px) 4px,
    4px calc(100% - 16px), 4px calc(100% - 16px),
    4px 4px, 4px 4px, 4px 4px, 4px 4px,
    calc(100% - 8px) calc(100% - 8px);
  background-position:
    8px 0, 8px 100%, 0 8px, 100% 8px,
    4px 4px, calc(100% - 4px) 4px, 4px calc(100% - 4px), calc(100% - 4px) calc(100% - 4px),
    center;
  background-repeat: no-repeat;
}

/* Reduced motion: the marquee stands still and wraps (see marquee.tsx) */
@media (prefers-reduced-motion: reduce) {
  .marquee-track { animation: none !important; transform: none !important; }
}

/* pixel3d-ui — navigation group styles (component-specific keyframes/utilities). */

/* ── unfold: accordion + collapsible content hinges open from its top edge ── */
@keyframes p3d-unfold {
  0% { height: 0; opacity: 0; transform: perspective(700px) rotateX(-62deg); }
  100% { height: var(--p3d-fold-h); opacity: 1; transform: perspective(700px) rotateX(0deg); }
}
@keyframes p3d-fold {
  0% { height: var(--p3d-fold-h); opacity: 1; transform: perspective(700px) rotateX(0deg); }
  100% { height: 0; opacity: 0; transform: perspective(700px) rotateX(-62deg); }
}
@utility unfold-motion {
  overflow: hidden;
  transform-origin: 50% 0;
  /* no fill on open: once unfolded the height returns to auto and follows its content */
  &[data-state="open"] { animation: p3d-unfold 340ms var(--ease-out-expo); }
  &[data-state="closed"] { animation: p3d-fold 200ms ease-in forwards; }
}
@utility unfold-accordion { --p3d-fold-h: var(--radix-accordion-content-height); }
@utility unfold-collapsible { --p3d-fold-h: var(--radix-collapsible-content-height); }

/* ── a vertical 4px dotted pixel rule (pairs with pixel-rule) ── */
@utility pixel-rule-y {
  width: 4px;
  background-image: linear-gradient(180deg, currentColor 50%, transparent 50%);
  background-size: 4px 8px;
}

/* ── scroll-area thumb: an ink block with 2px stepped corners ── */
@utility pixel-thumb {
  background: transparent;
  &::before {
    content: "";
    position: absolute;
    inset: 2px;
    background: var(--color-ink);
    box-shadow:
      0 -2px 0 0 var(--color-ink), 0 2px 0 0 var(--color-ink),
      -2px 0 0 0 var(--color-ink), 2px 0 0 0 var(--color-ink);
  }
}

/* ── mark: a pink highlighter sticker behind inline text ── */
@utility mark-sticker {
  background: var(--color-pink);
  color: var(--color-ink);
  padding: 0 0.2em;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
  filter:
    drop-shadow(4px 0 0 var(--p3d-cut)) drop-shadow(-4px 0 0 var(--p3d-cut))
    drop-shadow(0 4px 0 var(--p3d-cut)) drop-shadow(0 -4px 0 var(--p3d-cut))
    drop-shadow(0 3px 3px rgb(var(--p3d-shadow) / 0.24));
}

/* ── sidebar: the mobile panel slides in from the left ── */
@utility sidebar-slide {
  transition: transform 320ms var(--ease-out-expo), visibility 0s linear 320ms;
  &[data-state="closed"] { transform: translateX(calc(-100% - 24px)); visibility: hidden; }
  &[data-state="open"] { transform: translateX(0); visibility: visible; transition-delay: 0s; }
}

/* ── button group: buttons fused into one straight sticker strip ──
 * Unlayered on purpose: it has to beat the buttons' own peel/tilt utilities.
 * Each child keeps its ink face but drops its own kiss-cut; the group draws one cut
 * around the whole strip. Only the two outer ends keep their stepped notches. */
[data-slot="button-group"] > * {
  filter: none;
  transform: none;
  --p3d-tilt: 0deg;
  transition: transform 90ms;
}
[data-slot="button-group"] > *::before {
  inset: 0;
  box-shadow: none;
  transition: filter 120ms;
}
[data-slot="button-group"] > :hover:not(:disabled):not([aria-disabled="true"])::before { filter: brightness(0.92); }
[data-slot="button-group"] > :active:not(:disabled):not([aria-disabled="true"]) { transform: translateY(1px); }
[data-slot="button-group"] > :active:not(:disabled):not([aria-disabled="true"])::before { filter: brightness(0.85); }
[data-slot="button-group"]:has(:focus-visible) { --p3d-cut: var(--color-sky); }

/* outer ends keep the 1-step notch */
[data-slot="button-group"][data-orientation="horizontal"] > :first-child::before {
  inset: 4px 0 4px 4px;
  box-shadow: 0 -4px 0 0 var(--face), 0 4px 0 0 var(--face), -4px 0 0 0 var(--face);
}
[data-slot="button-group"][data-orientation="horizontal"] > :last-child::before {
  inset: 4px 4px 4px 0;
  box-shadow: 0 -4px 0 0 var(--face), 0 4px 0 0 var(--face), 4px 0 0 0 var(--face);
}
[data-slot="button-group"][data-orientation="vertical"] > :first-child::before {
  inset: 4px 4px 0 4px;
  box-shadow: 0 -4px 0 0 var(--face), -4px 0 0 0 var(--face), 4px 0 0 0 var(--face);
}
[data-slot="button-group"][data-orientation="vertical"] > :last-child::before {
  inset: 0 4px 4px 4px;
  box-shadow: 0 4px 0 0 var(--face), -4px 0 0 0 var(--face), 4px 0 0 0 var(--face);
}
[data-slot="button-group"] > :only-child::before {
  inset: 4px;
  box-shadow:
    0 -4px 0 0 var(--face), 0 4px 0 0 var(--face),
    -4px 0 0 0 var(--face), 4px 0 0 0 var(--face);
}

/* ink pixel dividers between segments */
[data-slot="button-group"] > * + *::after {
  content: "";
  position: absolute;
  pointer-events: none;
  color: var(--color-ink);
}
[data-slot="button-group"][data-orientation="horizontal"] > * + *::after {
  left: -2px;
  top: 8px;
  bottom: 8px;
  width: 4px;
  background-image: linear-gradient(180deg, currentColor 50%, transparent 50%);
  background-size: 4px 8px;
}
[data-slot="button-group"][data-orientation="vertical"] > * + *::after {
  top: -2px;
  left: 8px;
  right: 8px;
  height: 4px;
  background-image: linear-gradient(90deg, currentColor 50%, transparent 50%);
  background-size: 8px 4px;
}

/* pixel3d-ui — overlays group styles (component-specific keyframes/utilities). */

/* ── keyframes ─────────────────────────────────────────────── */
@keyframes p3d-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes p3d-fade-out {
  from { opacity: 1; }
  to { opacity: 0; }
}
/* a big sticker slapped onto the screen: drops in a little crooked, settles straight */
@keyframes p3d-slap-in {
  0% { transform: translateY(-28px) rotate(-4deg) scale(1.08); opacity: 0; }
  55% { transform: translateY(3px) rotate(0.8deg) scale(0.985); opacity: 1; }
  100% { transform: translateY(0) rotate(0deg) scale(1); opacity: 1; }
}
/* sheets slide in from their edge with a small settle */
@keyframes p3d-sheet-in-right {
  from { transform: translateX(calc(100% + 32px)) rotate(2deg); }
  to { transform: none; }
}
@keyframes p3d-sheet-out-right {
  to { transform: translateX(calc(100% + 32px)) rotate(2deg); }
}
@keyframes p3d-sheet-in-left {
  from { transform: translateX(calc(-100% - 32px)) rotate(-2deg); }
  to { transform: none; }
}
@keyframes p3d-sheet-out-left {
  to { transform: translateX(calc(-100% - 32px)) rotate(-2deg); }
}
@keyframes p3d-sheet-in-top {
  from { transform: translateY(calc(-100% - 32px)) rotate(-1deg); }
  to { transform: none; }
}
@keyframes p3d-sheet-out-top {
  to { transform: translateY(calc(-100% - 32px)) rotate(-1deg); }
}
@keyframes p3d-sheet-in-bottom {
  from { transform: translateY(calc(100% + 32px)) rotate(1deg); }
  to { transform: none; }
}
@keyframes p3d-sheet-out-bottom {
  to { transform: translateY(calc(100% + 32px)) rotate(1deg); }
}
/* toasts: a crooked sticker dropped onto the lid with a stepped (pixel) bounce.
   Uses the individual translate/rotate properties so it composes with sonner's transform. */
@keyframes p3d-toast-drop {
  0% { translate: 0 -40px; rotate: -10deg; opacity: 0; }
  35% { translate: 0 6px; rotate: var(--p3d-tilt, 0deg); opacity: 1; }
  55% { translate: 0 -8px; }
  75% { translate: 0 2px; }
  88% { translate: 0 -2px; }
  100% { translate: 0 0; rotate: var(--p3d-tilt, 0deg); opacity: 1; }
}

/* ── utilities ─────────────────────────────────────────────── */
/* ink overlay behind dialogs / sheets */
@utility overlay-fade {
  &[data-state="open"] { animation: p3d-fade-in 240ms var(--ease-out-expo) both; }
  &[data-state="closed"] { animation: p3d-fade-out 160ms ease-in both; }
}

/* dialog / alert-dialog content */
@utility dialog-motion {
  &[data-state="open"] { animation: p3d-slap-in 420ms var(--ease-out-expo) both; }
  &[data-state="closed"] { animation: p3d-lift-out 180ms ease-in both; }
}

/* sheet content; reads data-side="top|right|bottom|left" */
@utility sheet-motion {
  &[data-side="right"][data-state="open"] { animation: p3d-sheet-in-right 460ms var(--ease-out-expo) both; }
  &[data-side="right"][data-state="closed"] { animation: p3d-sheet-out-right 220ms ease-in both; }
  &[data-side="left"][data-state="open"] { animation: p3d-sheet-in-left 460ms var(--ease-out-expo) both; }
  &[data-side="left"][data-state="closed"] { animation: p3d-sheet-out-left 220ms ease-in both; }
  &[data-side="top"][data-state="open"] { animation: p3d-sheet-in-top 460ms var(--ease-out-expo) both; }
  &[data-side="top"][data-state="closed"] { animation: p3d-sheet-out-top 220ms ease-in both; }
  &[data-side="bottom"][data-state="open"] { animation: p3d-sheet-in-bottom 460ms var(--ease-out-expo) both; }
  &[data-side="bottom"][data-state="closed"] { animation: p3d-sheet-out-bottom 220ms ease-in both; }
}

/* Radix Tooltip uses delayed-open / instant-open instead of open */
@utility tooltip-motion {
  &[data-state="delayed-open"], &[data-state="instant-open"] {
    animation: p3d-drop-in 220ms var(--ease-out-expo) both;
  }
  &[data-state="closed"] { animation: p3d-lift-out 120ms ease-in both; }
}

/* A flat pixel block with 1-step notched corners, painted with --fill (no pseudo-elements).
   Menu / command highlights, key caps, and the toast face. */
@utility notch-fill {
  background:
    linear-gradient(var(--fill, transparent), var(--fill, transparent)) center / calc(100% - 8px) 100% no-repeat,
    linear-gradient(var(--fill, transparent), var(--fill, transparent)) center / 100% calc(100% - 8px) no-repeat;
}

/* The toast sticker. Sonner owns ::before/::after (swipe hit areas), position and transform,
   so the face is painted with background layers and the tilt uses the `rotate` property. */
@utility toast-sticker {
  --p3d-sh: 0 6px 5px rgb(var(--p3d-shadow) / 0.28);
  --fill: var(--face, var(--color-paper));
  background:
    linear-gradient(var(--fill), var(--fill)) center / calc(100% - 8px) 100% no-repeat,
    linear-gradient(var(--fill), var(--fill)) center / 100% calc(100% - 8px) no-repeat;
  filter:
    drop-shadow(4px 0 0 var(--p3d-cut)) drop-shadow(-4px 0 0 var(--p3d-cut))
    drop-shadow(0 4px 0 var(--p3d-cut)) drop-shadow(0 -4px 0 var(--p3d-cut))
    drop-shadow(var(--p3d-sh));
  rotate: var(--p3d-tilt, 0deg);
  animation: p3d-toast-drop 560ms steps(4, end) backwards;
}

/* Unlayered on purpose: beats sonner's injected (unlayered) slide-from-edge start, so the
   toast drops in with our bounce instead of also sliding 100% from the edge. */
[data-sonner-toast][data-mounted="false"].toast-sticker {
  --y: translateY(0);
}

/*
 * pixel3d-ui — the sticker material.
 * Import once after tailwindcss:  @import "tailwindcss"; @import "@pixel3d/ui/styles.css";
 * Every component is a die-cut sticker: a pixel-stepped silhouette (::before + stepped
 * box-shadow bands) inside a white kiss-cut border (stacked drop-shadow filter).
 */
@import "@fontsource-variable/bricolage-grotesque";
@import "./overlays.css";
@import "./forms.css";
@import "./navigation.css";
@import "./data.css";
@import "./kit.css";
@import "./transitions.css";

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  /* pixel3d owns its own font token so a host's --font-sans (e.g. shadcn's @theme inline) can't override it */
  --font-p3d: "Bricolage Grotesque Variable", ui-sans-serif, system-ui, sans-serif;
  --font-sans: var(--font-p3d);
  --font-mono: ui-monospace, "Cascadia Code", "SF Mono", Menlo, monospace;

  /* vinyl inks — one job each */
  --color-pink: #ff3d8b;   /* act */
  --color-lime: #b6f23a;   /* chosen / success */
  --color-sky: #36b8ff;    /* on / focus / info */
  --color-tomato: #ff5a36; /* destroy / error */
  --color-butter: #ffd23f; /* warn */
  --color-ink: #141414;
  --color-ink-soft: #4a4d55;
  --color-placeholder: #62656c; /* 5.9:1 on paper: AA, still reads as a hint */
  --color-paper: #ffffff;

  /* the lid (theme-aware) */
  --color-lid: var(--p3d-lid);
  --color-lid-deep: var(--p3d-lid-deep);
  --color-on-lid: var(--p3d-on-lid);
  --color-on-lid-soft: var(--p3d-on-lid-soft);

  /* No Squint: the smallest step is 14px */
  --text-xs: 0.875rem;
  --text-xs--line-height: 1.35;

  --ease-peel: cubic-bezier(0.3, 1.7, 0.5, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);

  /* The Stepped Edge Rule: no smooth radius exists in this system */
  --radius-*: initial;
}

:root {
  --p3d-lid: #cdd1d8;
  --p3d-lid-deep: #bfc4cc;
  --p3d-on-lid: #141414;
  --p3d-on-lid-soft: #3e4148;
  --p3d-cut: #ffffff;
  --p3d-shadow: 20 20 30;
  --p3d-u: 4px;
  color-scheme: light;
}
.dark {
  --p3d-lid: #2b2e35;
  --p3d-lid-deep: #23262c;
  --p3d-on-lid: #f2f3f5;
  --p3d-on-lid-soft: #b9bdc6;
  --p3d-shadow: 0 0 0;
  color-scheme: dark;
}

@layer base {
  html {
    background: var(--p3d-lid);
    color: var(--p3d-on-lid);
    font-family: var(--font-p3d);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    scrollbar-color: var(--color-ink) var(--p3d-lid-deep);
  }
  body { background: var(--p3d-lid); font-size: 1rem; line-height: 1.55; }
  ::selection { background: var(--color-pink); color: var(--color-ink); }
  input, textarea, [contenteditable] { caret-color: var(--color-pink); }
  :focus-visible { outline: 4px solid var(--color-sky); outline-offset: 4px; }
  table { font-variant-numeric: tabular-nums; }
  h1, h2, h3, h4 { text-wrap: balance; overflow-wrap: break-word; }
  p, li, figcaption { text-wrap: pretty; }
  ::-webkit-scrollbar { width: 14px; height: 14px; }
  ::-webkit-scrollbar-track { background: var(--p3d-lid-deep); }
  ::-webkit-scrollbar-thumb { background: var(--color-ink); border: 4px solid var(--p3d-lid-deep); }
}

/* Unlayered on purpose: the lid and the face win over a host app's base layer
   (shadcn's default globals.css paints body bg-background + its own font). */
html, body { background-color: var(--p3d-lid); font-family: var(--font-p3d); }
/* The page never scrolls sideways. Peel scale, intros and resting tilt can poke a sticker
   a few px past the edge; clip (not hidden) keeps position: sticky working. */
body { overflow-x: clip; }

/* ── the sticker ──────────────────────────────────────────── */
/* 1-step notched corners (controls ≤ 48px tall) */
@utility sticker {
  --face: var(--color-paper);
  --p3d-sh: 0 6px 5px rgb(var(--p3d-shadow) / 0.28);
  position: relative;
  isolation: isolate;
  color: var(--color-ink);
  filter:
    drop-shadow(4px 0 0 var(--p3d-cut)) drop-shadow(-4px 0 0 var(--p3d-cut))
    drop-shadow(0 4px 0 var(--p3d-cut)) drop-shadow(0 -4px 0 var(--p3d-cut))
    drop-shadow(var(--p3d-sh));
  &::before {
    content: "";
    position: absolute;
    inset: 4px;
    z-index: -1;
    pointer-events: none;
    background: var(--face);
    box-shadow:
      0 -4px 0 0 var(--face), 0 4px 0 0 var(--face),
      -4px 0 0 0 var(--face), 4px 0 0 0 var(--face);
    transition: background-color 160ms, box-shadow 160ms;
  }
}
/* 3-step corners (cards, dialogs, sheets): add alongside `sticker` */
@utility sticker-lg {
  &::before {
    inset: 8px;
    box-shadow:
      0 -4px 0 0 var(--face), 0 -12px 0 -4px var(--face),
      0 4px 0 0 var(--face), 0 12px 0 -4px var(--face),
      -4px 0 0 0 var(--face), -12px 0 0 -4px var(--face),
      4px 0 0 0 var(--face), 12px 0 0 -4px var(--face);
  }
}
/* a sticker that lies flat: no lip shadow (pressed-in / selected) */
@utility sticker-flat { --p3d-sh: 0 0 0 transparent; }

/* faces */
@utility face-paper { --face: var(--color-paper); color: var(--color-ink); }
@utility face-pink { --face: var(--color-pink); color: var(--color-ink); }
@utility face-lime { --face: var(--color-lime); color: var(--color-ink); }
@utility face-sky { --face: var(--color-sky); color: var(--color-ink); }
@utility face-tomato { --face: var(--color-tomato); color: var(--color-ink); }
@utility face-butter { --face: var(--color-butter); color: var(--color-ink); }
@utility face-ink { --face: var(--color-ink); color: var(--color-paper); }
@utility face-lid { --face: var(--p3d-lid-deep); color: var(--p3d-on-lid); }

/* resting tilt (The Crooked Rule) — set --p3d-tilt per instance */
@utility crooked { transform: rotate(var(--p3d-tilt, 0deg)); }

/* The Peel Rule: hover lifts + straightens, press slaps */
@utility peel {
  transform: rotate(var(--p3d-tilt, 0deg));
  transition: transform 260ms var(--ease-peel), filter 260ms var(--ease-peel);
  will-change: transform;
  &:hover:not(:disabled):not([aria-disabled="true"]) {
    transform: translateY(-5px) rotate(0deg) scale(1.04);
    --p3d-sh: 0 14px 14px rgb(var(--p3d-shadow) / 0.24);
  }
  &:active:not(:disabled):not([aria-disabled="true"]) {
    transform: rotate(0deg) scale(0.94);
    --p3d-sh: 0 2px 2px rgb(var(--p3d-shadow) / 0.3);
    transition-duration: 90ms;
  }
}
/* gentler peel for big stickers: lift a corner in 3D instead of scaling */
@utility peel-3d {
  transform: perspective(900px) rotate(var(--p3d-tilt, 0deg));
  transition: transform 320ms var(--ease-peel), filter 320ms var(--ease-peel);
  &:hover {
    transform: perspective(900px) rotateX(5deg) rotateY(-4deg) translateY(-6px);
    --p3d-sh: 0 18px 18px rgb(var(--p3d-shadow) / 0.22);
  }
}

/* focus = the kiss-cut turns sky. A stepped focus ring for free. */
@utility focus-cut {
  outline: none;
  &:focus-visible { --p3d-cut: var(--color-sky); outline: none; }
}
@utility focus-within-cut {
  &:focus-within { --p3d-cut: var(--color-sky); }
}

/* disabled stickers are blank, flat and still */
@utility sticker-disabled {
  &:disabled, &[aria-disabled="true"], &[data-disabled] {
    --face: #e4e6ea;
    --p3d-sh: 0 0 0 transparent;
    color: var(--color-ink-soft);
    cursor: not-allowed;
  }
}

/* pixel icons render crisp */
@utility pixel-icon {
  shape-rendering: crispEdges;
  image-rendering: pixelated;
  flex-shrink: 0;
}

/* a 4px dotted pixel rule */
@utility pixel-rule {
  height: 4px;
  background-image: linear-gradient(90deg, currentColor 50%, transparent 50%);
  background-size: 8px 4px;
}

/* ── motion keyframes ─────────────────────────────────────── */
@keyframes p3d-land {
  0% { transform: scale(1.3) rotate(-14deg) translateY(-6px); opacity: 0; }
  60% { transform: scale(0.94) rotate(-2deg); opacity: 1; }
  100% { transform: scale(1) rotate(-4deg); opacity: 1; }
}
@keyframes p3d-peel-off {
  0% { transform: scale(1) rotate(-4deg); opacity: 1; }
  100% { transform: scale(1.1) rotate(12deg) translateY(-8px); opacity: 0; }
}
@keyframes p3d-slap {
  0% { transform: scale(1.12) rotate(var(--p3d-tilt, 0deg)); }
  55% { transform: scale(0.96) rotate(var(--p3d-tilt, 0deg)); }
  100% { transform: scale(1) rotate(var(--p3d-tilt, 0deg)); }
}
/* stamp: the whole sticker thunks down when its state changes (two names so it re-runs) */
@keyframes p3d-stamp { 0% { transform: scale(1.18); } 55% { transform: scale(0.92); } 100% { transform: scale(1); } }
@keyframes p3d-unstamp { 0% { transform: scale(0.88); } 100% { transform: scale(1); } }
@keyframes p3d-drop-in {
  0% { transform: translateY(-14px) rotate(-6deg) scale(1.06); opacity: 0; }
  100% { transform: translateY(0) rotate(var(--p3d-tilt, 0deg)) scale(1); opacity: 1; }
}
@keyframes p3d-lift-out {
  0% { transform: translateY(0) rotate(var(--p3d-tilt, 0deg)); opacity: 1; }
  100% { transform: translateY(-10px) rotate(6deg) scale(1.03); opacity: 0; }
}
@keyframes p3d-pixel-spin {
  to { transform: rotate(360deg); }
}
@keyframes p3d-shimmer {
  0% { background-position: 0 0; }
  100% { background-position: 32px 0; }
}

@utility animate-land { animation: p3d-land 360ms var(--ease-peel) both; }
@utility animate-peel-off { animation: p3d-peel-off 200ms ease-in both; }
@utility animate-stamp { animation: p3d-stamp 320ms var(--ease-peel); }
@utility animate-unstamp { animation: p3d-unstamp 220ms var(--ease-peel); }
@utility animate-slap { animation: p3d-slap 320ms var(--ease-peel); }
@utility animate-drop-in { animation: p3d-drop-in 320ms var(--ease-out-expo) both; }
@utility animate-lift-out { animation: p3d-lift-out 180ms ease-in both; }

/* overlays (Radix data-state) */
@utility overlay-motion {
  &[data-state="open"] { animation: p3d-drop-in 320ms var(--ease-out-expo) both; }
  &[data-state="closed"] { animation: p3d-lift-out 160ms ease-in both; }
}

/* The Still Rule */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 1ms !important;
  }
  .peel:hover, .peel-3d:hover { transform: rotate(var(--p3d-tilt, 0deg)) !important; }
}

/* ── transitions: route changes + intros ──────────────────────────────────
   Snappy first. A route change never waits: the router swaps the page and the new
   <PageSheet> slides in from 20px right over 180ms (PageTransitions, Web Animations).

   Intros animate the individual transform properties (translate / rotate / scale),
   never `transform`, so they compose with crooked tilt and peel physics. Fill mode is
   `backwards`: once a sticker has landed, its own transform is back in charge. */

@keyframes p3d-intro {
  from { opacity: 0; translate: 0 -12px; rotate: var(--p3d-intro-rot, 0deg); scale: var(--p3d-intro-scale, 1); }
}

/* a single sticker that gets stuck on when it mounts; order it with --p3d-i */
@utility intro {
  animation: p3d-intro 280ms var(--ease-peel) backwards;
  animation-delay: calc(var(--p3d-intro-base, 0ms) + var(--p3d-i, 0) * 40ms);
}

/* every direct child gets stuck on in order (capped at the 7th, so nothing waits long) */
@utility intro-stagger {
  & > * {
    animation: p3d-intro 280ms var(--ease-peel) backwards;
    animation-delay: calc(var(--p3d-intro-base, 0ms) + var(--p3d-i, 0) * 40ms);
  }
  & > :nth-child(2) { --p3d-i: 1; }
  & > :nth-child(3) { --p3d-i: 2; }
  & > :nth-child(4) { --p3d-i: 3; }
  & > :nth-child(5) { --p3d-i: 4; }
  & > :nth-child(6) { --p3d-i: 5; }
  & > :nth-child(n + 7) { --p3d-i: 6; }
}

/* the page-level stagger: plays on a hard load only. After an in-app navigation the
   PageSheet slide carries the change, so the page doesn't animate twice. */
@utility intro-page {
  :root:not([data-p3d-navigated]) & > * {
    animation: p3d-intro 280ms var(--ease-peel) backwards;
    animation-delay: calc(var(--p3d-i, 0) * 40ms);
  }
  & > :nth-child(2) { --p3d-i: 1; }
  & > :nth-child(3) { --p3d-i: 2; }
  & > :nth-child(4) { --p3d-i: 3; }
  & > :nth-child(5) { --p3d-i: 4; }
  & > :nth-child(6) { --p3d-i: 5; }
  & > :nth-child(n + 7) { --p3d-i: 6; }
}

/* Blocks, text and full-width things drop in straight (a rotated full-width block pokes
   past the page edge, and long text never tilts: the Crooked Rule). Small loose stickers
   may also tumble in. */
@utility intro-tumble { --p3d-intro-rot: -6deg; --p3d-intro-scale: 1.06; }

/* <Reveal>: holds its stickers back until it scrolls into view */
[data-slot="reveal"][data-state="waiting"] > * { animation: none; opacity: 0; }

/* The Still Rule: nothing animates in */
@media (prefers-reduced-motion: reduce) {
  .intro, .intro-stagger > *, .intro-page > * { animation: none !important; }
  [data-slot="reveal"][data-state="waiting"] > * { opacity: 1; }
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";
import * as React from "react";

/** Merge Tailwind classes (shadcn convention). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Deterministic hash → number in [-1, 1]. */
export function seededUnit(seed: string) {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) h = Math.imul(h ^ seed.charCodeAt(i), 16777619);
  return ((h >>> 0) % 2001) / 1000 - 1;
}

export type Tilt = number | "auto" | false;

/**
 * The Crooked Rule: small standalone stickers rest tilted between -max° and +max°.
 * "auto" derives a stable angle from React's useId, so SSR and client agree.
 * Returns a style object carrying --p3d-tilt.
 */
export function useTilt(tilt: Tilt = "auto", max = 2.5): React.CSSProperties {
  const id = React.useId();
  if (tilt === false) return { ["--p3d-tilt" as string]: "0deg" };
  const deg = typeof tilt === "number" ? tilt : Math.round(seededUnit(id) * max * 10) / 10;
  return { ["--p3d-tilt" as string]: `${deg}deg` };
}
